self.KB_CONTENT["card:753508"]={"id":"card:753508","ty":"card","sourceId":"753508","title":"『產生分錄底稿-應付憑單』的作業目的為何？","ver":"iGP","topic":"應付憑單","keywords":["應付憑單","傳票","分錄","底稿"],"y":"explain","answer":"在產生分錄底稿作業中之單據來源選擇應付憑單時，自動開立傳票產生應付憑單之分錄底稿資料。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
