self.KB_CONTENT["card:751982"]={"id":"card:751982","ty":"card","sourceId":"751982","title":"『會計傳票帳冊清除作業』中的『』為何？","ver":"iGP","topic":"傳票","keywords":["傳票","清除"],"y":"other","answer":"選擇建立作業* 是否選擇建立作業。僅接受「Y」或「N」之判斷值。* 預設不勾選建立作業，避免使用者不小心將其他不需要清除的檔案資料給清除了。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
