self.KB_CONTENT["card:793610"]={"id":"card:793610","ty":"card","sourceId":"793610","title":"『PACKING LIST』中的『選擇確認狀態』為何？","ver":"GP4以上","topic":"狀態","keywords":["狀態","作廢"],"y":"other","answer":"選擇確認狀態* 區分Y.已確認、N.未確認、V.作廢及全部 (不須篩選Y/N/V都印) 。預設「已確認」狀態。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
