self.KB_CONTENT["card:779647"]={"id":"card:779647","ty":"card","sourceId":"779647","title":"『委外加工計價設定作業』的作業目的為何？","ver":"GP4以上","topic":"加工","keywords":["加工","價單","計價","依據"],"y":"explain","answer":"建立委外加工的計價方式，作為後續加工核價單建立作業之選擇依據。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
self.KB_CONTENT["card:779661"]={"id":"card:779661","ty":"card","sourceId":"779661","title":"『BOM參數設定作業』的作業重點有哪些？","ver":"GP4以上","topic":"狀況","keywords":["狀況"],"y":"explain","answer":"■作業重點1.作業一經設定請勿隨意修改，必須修改時，請保持在單一使用者狀況修改。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
self.KB_CONTENT["card:779834"]={"id":"card:779834","ty":"card","sourceId":"779834","title":"『託外退貨單憑證(IDL)(IDLR27)』的作業目的為何？","ver":"GP4以上","topic":"貨單","keywords":["貨單","憑證","退貨"],"y":"explain","answer":"將託外退貨單印成憑證表格。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
